def min_points(intervals):
    if not intervals:
        return 0
    # Sort intervals by end point
    intervals = sorted(intervals, key=lambda x: x[1])
    points = []
    last_point = None
    for start, end in intervals:
        if last_point is None or last_point < start:
            # Need a new point; place it at the end of this interval
            last_point = end
            points.append(last_point)
    return len(points)
